/* Decode the request of n bytes at req, which came on ch, call its handler,
 * encode the reply into rep (NETCTL_REP_MAX bytes) and the handles it carries
 * into rhs (IDL_REP_HANDLES slots; *rhn of them). Returns the reply's
 * length: 0 means no reply (the request has no txid, or a `later`
 * handler answers it itself). No I/O; the caller sends the reply with the
 * handles, or closes them if it can't. */
static inline uint32_t netctl_dispatch_on(handle_t ch, const struct netctl_ops *ops, void *ctx,
                                          const void *req, uint32_t n, void *rep, handle_t *rhs,
                                          uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    (void)ch;
    if (n < sizeof(uint32_t))
        return 0;
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    if (n < sizeof(struct idl_req_hdr))
        return sizeof(*idl_h);
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    case NETCTL_SET_IPV4: {
        const struct netctl_set_ipv4_req *idl_q = (const struct netctl_set_ipv4_req *)req;
        struct netctl_set_ipv4_rep *idl_r = (struct netctl_set_ipv4_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->set_ipv4) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->set_ipv4(ctx, idl_q->address, idl_q->mask, idl_q->gateway);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case NETCTL_SET_DNS: {
        const struct netctl_set_dns_req *idl_q = (const struct netctl_set_dns_req *)req;
        struct netctl_set_dns_rep *idl_r = (struct netctl_set_dns_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->set_dns) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->set_dns(ctx, idl_q->first, idl_q->second);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case NETCTL_CLEAR: {
        const struct netctl_clear_req *idl_q = (const struct netctl_clear_req *)req;
        struct netctl_clear_rep *idl_r = (struct netctl_clear_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->clear) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->clear(ctx);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case NETCTL_INFO: {
        const struct netctl_info_req *idl_q = (const struct netctl_info_req *)req;
        struct netctl_info_rep *idl_r = (struct netctl_info_rep *)rep;
        uint32_t out_address = 0;
        uint32_t out_mask = 0;
        uint32_t out_gateway = 0;
        uint32_t out_dns1 = 0;
        uint32_t out_dns2 = 0;
        uint8_t out_mac[6];
        for (uint32_t idl_i = 0; idl_i < 6; idl_i++)
            out_mac[idl_i] = 0;
        uint8_t out_device = 0;
        uint8_t out_link = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->info) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->info(ctx, &out_address, &out_mask, &out_gateway, &out_dns1, &out_dns2, out_mac, &out_device, &out_link);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->address = out_address;
        idl_r->mask = out_mask;
        idl_r->gateway = out_gateway;
        idl_r->dns1 = out_dns1;
        idl_r->dns2 = out_dns2;
        for (uint32_t idl_i = 0; idl_i < 6; idl_i++)
            idl_r->mac[idl_i] = out_mac[idl_i];
        idl_r->device = out_device;
        idl_r->link = out_link;
        return sizeof(*idl_r);
    }
    case NETCTL_STATS: {
        const struct netctl_stats_req *idl_q = (const struct netctl_stats_req *)req;
        struct netctl_stats_rep *idl_r = (struct netctl_stats_rep *)rep;
        uint64_t out_rx_frames = 0;
        uint64_t out_rx_refused = 0;
        uint64_t out_tx_frames = 0;
        uint64_t out_tx_dropped = 0;
        uint64_t out_echo_replies = 0;
        uint64_t out_icmp_errors = 0;
        uint64_t out_icmp_limited = 0;
        uint32_t out_link_dropped = 0;
        uint32_t out_arp_dropped = 0;
        uint32_t out_ip_dropped = 0;
        uint32_t out_icmp_dropped = 0;
        uint32_t out_udp_dropped = 0;
        uint32_t out_bad_checksums = 0;
        uint32_t out_rx_buffers_used = 0;
        uint32_t out_heap_used = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->stats) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->stats(ctx, &out_rx_frames, &out_rx_refused, &out_tx_frames, &out_tx_dropped, &out_echo_replies, &out_icmp_errors, &out_icmp_limited, &out_link_dropped, &out_arp_dropped, &out_ip_dropped, &out_icmp_dropped, &out_udp_dropped, &out_bad_checksums, &out_rx_buffers_used, &out_heap_used);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->rx_frames = out_rx_frames;
        idl_r->rx_refused = out_rx_refused;
        idl_r->tx_frames = out_tx_frames;
        idl_r->tx_dropped = out_tx_dropped;
        idl_r->echo_replies = out_echo_replies;
        idl_r->icmp_errors = out_icmp_errors;
        idl_r->icmp_limited = out_icmp_limited;
        idl_r->link_dropped = out_link_dropped;
        idl_r->arp_dropped = out_arp_dropped;
        idl_r->ip_dropped = out_ip_dropped;
        idl_r->icmp_dropped = out_icmp_dropped;
        idl_r->udp_dropped = out_udp_dropped;
        idl_r->bad_checksums = out_bad_checksums;
        idl_r->rx_buffers_used = out_rx_buffers_used;
        idl_r->heap_used = out_heap_used;
        return sizeof(*idl_r);
    }
    case NETCTL_DEVICE: {
        const struct netctl_device_req *idl_q = (const struct netctl_device_req *)req;
        struct netctl_device_rep *idl_r = (struct netctl_device_rep *)rep;
        uint8_t out_session = 0;
        uint16_t out_vlan = 0;
        uint32_t out_speed = 0;
        uint32_t out_sessions = 0;
        uint64_t out_ring_errors = 0;
        uint64_t out_rx_bad = 0;
        uint64_t out_tx_full = 0;
        uint8_t out_chip[16];
        for (uint32_t idl_i = 0; idl_i < 16; idl_i++)
            out_chip[idl_i] = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->device) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->device(ctx, &out_session, &out_vlan, &out_speed, &out_sessions, &out_ring_errors, &out_rx_bad, &out_tx_full, out_chip);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->session = out_session;
        idl_r->vlan = out_vlan;
        idl_r->speed = out_speed;
        idl_r->sessions = out_sessions;
        idl_r->ring_errors = out_ring_errors;
        idl_r->rx_bad = out_rx_bad;
        idl_r->tx_full = out_tx_full;
        for (uint32_t idl_i = 0; idl_i < 16; idl_i++)
            idl_r->chip[idl_i] = out_chip[idl_i];
        return sizeof(*idl_r);
    }
    case NETCTL_DHCP_OPEN: {
        const struct netctl_dhcp_open_req *idl_q = (const struct netctl_dhcp_open_req *)req;
        struct netctl_dhcp_open_rep *idl_r = (struct netctl_dhcp_open_rep *)rep;
        handle_t out_socket = HANDLE_INVALID;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->dhcp_open) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->dhcp_open(ctx, &out_socket);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_socket != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_socket != HANDLE_INVALID)
                drv_handle_close(out_socket);
            return sizeof(*idl_h);
        }
        rhs[0] = out_socket;
        *rhn = 1;
        return sizeof(*idl_r);
    }
    case NETCTL_SUMMARY: {
        const struct netctl_summary_req *idl_q = (const struct netctl_summary_req *)req;
        struct netctl_summary_rep *idl_r = (struct netctl_summary_rep *)rep;
        uint8_t out_link = 0;
        uint32_t out_address = 0;
        uint32_t out_mask = 0;
        uint32_t out_speed = 0;
        uint64_t out_rx_bytes = 0;
        uint64_t out_tx_bytes = 0;
        uint8_t out_chip[16];
        for (uint32_t idl_i = 0; idl_i < 16; idl_i++)
            out_chip[idl_i] = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->summary) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->summary(ctx, &out_link, &out_address, &out_mask, &out_speed, &out_rx_bytes, &out_tx_bytes, out_chip);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->link = out_link;
        idl_r->address = out_address;
        idl_r->mask = out_mask;
        idl_r->speed = out_speed;
        idl_r->rx_bytes = out_rx_bytes;
        idl_r->tx_bytes = out_tx_bytes;
        for (uint32_t idl_i = 0; idl_i < 16; idl_i++)
            idl_r->chip[idl_i] = out_chip[idl_i];
        return sizeof(*idl_r);
    }
    }
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* netctl_dispatch_on without the channel (the protocol has no `later` method). */
static inline uint32_t netctl_dispatch(const struct netctl_ops *ops, void *ctx, const void *req, uint32_t n,
                                       void *rep, handle_t *rhs, uint32_t *rhn)
{
    return netctl_dispatch_on(HANDLE_INVALID, ops, ctx, req, n, rep, rhs, rhn);
}

/* Take the next message on ch into slot (idl_take), a slot with room for
 * the protocol's biggest request (ERR_INVALID_ARGS if it has less). The
 * reply waiting in *rep (NULL or empty: none) goes out first in the same
 * system call (idl_take_after). It never waits: ERR_SHOULD_WAIT when
 * nothing is queued. */
static inline status_t netctl_take_slot(handle_t ch, const struct idl_slot *slot,
                                        struct idl_reply *rep)
{
    if (slot->qcap < NETCTL_REQ_MAX)
        return ERR_INVALID_ARGS;
    if (rep && rep->ch != HANDLE_INVALID)
        return idl_take_after(ch, slot, rep);
    return idl_take(ch, slot);
}

/* Run the request in slot (taken by netctl_take_slot, or found there by a
 * successor), which came on ch: as netctl_dispatch_on, its reply built
 * in slot->r and the handles that reply carries put into rhs
 * (IDL_REP_HANDLES slots; *rhn of them). A request that carried handles is
 * answered ERR_INVALID_ARGS without its handler seeing it. Returns the
 * reply's length: 0 means no reply (no txid, or a `later` handler
 * answers it itself). No I/O; the caller sends the reply with the handles,
 * or closes them if it can't. */
static inline uint32_t netctl_run_slot(handle_t ch, const struct idl_slot *slot,
                                       const struct netctl_ops *ops, void *ctx, handle_t *rhs, uint32_t *rhn)
{
    *rhn = 0;
    if (*slot->n >= sizeof(uint32_t) && *slot->nh)
        return idl_refuse(slot);
    return netctl_dispatch_on(ch, ops, ctx, slot->q, *slot->n, slot->r, rhs, rhn);
}

/* Is the method with this wire ordinal idempotent (its keyword in the
 * .idl): run again on the state its first run left, it gives the same
 * result and the same answer? A server that keeps nothing across a
 * restart may run such a request again; any other it answers with an
 * error. */
static inline bool netctl_idempotent(uint32_t ordinal)
{
    (void)ordinal;
    return false;   /* no method is marked */
}

/* Take one message off ch and answer it. OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t netctl_serve_one(handle_t ch, const struct netctl_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[NETCTL_REQ_MAX];
    _Alignas(8) uint8_t idl_r[NETCTL_REP_MAX];
    handle_t idl_hs[IDL_READ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, sizeof(idl_q), &idl_n, idl_hs, IDL_READ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL)
        return idl_drain(ch, idl_n, idl_nh);
    if (idl_st != OK)
        return idl_st;
    if (idl_nh) {
        idl_close_all(idl_hs, idl_nh);
        idl_reply_status(ch, idl_q, idl_n, ERR_INVALID_ARGS);
        return OK;
    }
    handle_t idl_rhs[IDL_REP_HANDLES];
    uint32_t idl_rhn = 0;
    uint32_t idl_rn = netctl_dispatch_on(ch, ops, ctx, idl_q, idl_n, idl_r, idl_rhs, &idl_rhn);
    if (!idl_rn || drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn) != OK)
        idl_close_all(idl_rhs, idl_rhn);   /* not sent: they're still ours */
    return OK;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). Each reply
 * goes out in the system call that takes the next request
 * (idl_serve_next). */
static inline status_t netctl_serve(handle_t ch, const struct netctl_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[NETCTL_REQ_MAX];
    _Alignas(8) uint8_t idl_r[NETCTL_REP_MAX];
    handle_t idl_rhs[IDL_REP_HANDLES];
    struct idl_serve idl_s = {
        .ch = ch, .q = idl_q, .qcap = sizeof(idl_q), .r = idl_r, .rhs = idl_rhs,
    };
    for (;;) {
        status_t idl_st = idl_serve_next(&idl_s);
        if (idl_st == ERR_PEER_CLOSED)
            return OK;
        if (idl_st != OK)
            return idl_st;
        idl_s.rn = netctl_dispatch_on(ch, ops, ctx, idl_q, idl_s.n, idl_r, idl_rhs, &idl_s.rhn);
    }
}
